 71	/* Task 1: Nháy LED1 (PG6) theo chu kỳ 1000 ms (500 ms bật, 500 ms tắt) */
 72	static void vTaskLED1(void *pvParameters)
 73	{
 74	    (void)pvParameters;
 75	    for (;;) {
 76	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
 77	        vTaskDelay(pdMS_TO_TICKS(500));
 78	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
 79	        vTaskDelay(pdMS_TO_TICKS(500));
 80	    }
 81	}
