 95	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queues */
 96	static void vTaskButton(void *pvParameters)
 97	{
 98	    (void)pvParameters;
 99	    uint8_t prev_state = 0;
100	
101	    for (;;) {
102	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
103	        if (state && !prev_state) {
104	            uint32_t msg = 1;
105	            if (xButtonQueue != NULL) {
106	                xQueueSend(xButtonQueue, &msg, 0);
107	            }
108	            if (xUIQueue != NULL) {
109	                xQueueSend(xUIQueue, &msg, 0);
110	            }
111	        }
112	        prev_state = state;
113	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
114	    }
115	}
