117	/* Task 3: Chờ tín hiệu từ Queue để đổi trạng thái LED3 (PD5) */
118	static void vTaskLED3(void *pvParameters)
119	{
120	    (void)pvParameters;

121	    uint32_t rx_msg = 0;
122	    uint8_t led_state = 0;
123	
124	    for (;;) {
125	        if (xQueueReceive(xButtonQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
126	            led_state = !led_state;
127	            if (led_state) {
128	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
129	            } else {
130	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
131	            }
132	        }
133	    }
134	}
